#!/usr/bin/env python3
"""Verify that a Windows build preserves its reviewed, patched source inputs."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess


PINS = {
    "backend": "5ac7edc207866569334175e4ed8a7517971547f6",
    "frontend": "60be4b0f9a646109fd9fdf448bacd41477234091",
    "sdk": "3cffbc82429b6165ceec2714f0f0d9ae48f55596",
}

# These are the only build-generated files inside the reviewed source trees.
# Keep the list exact: for example, the shader .inc files beside these PDBs
# remain source inputs and are still covered by the ordinary source hashes.
GENERATED_OUTPUTS = {
    "backend/src/CommitHash.autogenerated": {
        "generator": "backend/MakeCommitHash.bat (invoked by CMake PRE_BUILD)",
        "inputs": ["backend/MakeCommitHash.bat", "backend/CMakeLists.txt"],
        "kind": "build identity header; embeds pinned backend/SDK revisions and dynamic build metadata",
    },
    "backend/src/mods/vr/shaders/Compiled/alpha_luminance_sprite_ps_SpritePixelShader.pdb": {
        "generator": "backend/src/mods/vr/shaders/compile_shaders.bat (CMake PRE_BUILD; DXC or FXC)",
        "inputs": ["backend/src/mods/vr/shaders/compile_shaders.bat",
                   "backend/src/mods/vr/shaders/alpha_luminance_sprite_ps.fx",
                   "backend/CMakeLists.txt"],
        "kind": "compiler-generated shader debug database",
    },
    "backend/src/mods/vr/shaders/Compiled/alpha_luminance_sprite_ps_SpriteVertexShader.pdb": {
        "generator": "backend/src/mods/vr/shaders/compile_shaders.bat (CMake PRE_BUILD; DXC or FXC)",
        "inputs": ["backend/src/mods/vr/shaders/compile_shaders.bat",
                   "backend/src/mods/vr/shaders/alpha_luminance_sprite_ps.fx",
                   "backend/CMakeLists.txt"],
        "kind": "compiler-generated shader debug database",
    },
    "frontend/UEVR/FilteredExecutables.json": {
        "generator": "frontend/UEVR/UEVR.csproj pre-build hash_executables.py",
        "inputs": ["frontend/UEVR/hash_executables.py",
                   "frontend/UEVR/PlainTextFilteredExecutables.json",
                   "frontend/UEVR/UEVR.csproj"],
        "kind": "deterministic JSON list of uppercase SHA-256 executable-name hashes",
    },
}
GENERATED_PATHS = frozenset(GENERATED_OUTPUTS)


def git(root: Path, *arguments: str) -> str:
    return subprocess.check_output(["git", "-C", str(root), *arguments], text=True).strip()


def inspect(backend: Path, frontend: Path) -> dict:
    roots = {"backend": backend, "frontend": frontend,
             "sdk": backend / "dependencies/submodules/UESDK"}
    for name, root in roots.items():
        if git(root, "rev-parse", "HEAD") != PINS[name]:
            raise RuntimeError(f"Unexpected {name} source revision")
    if git(roots["sdk"], "status", "--porcelain", "--untracked-files=all"):
        raise RuntimeError("The restricted SDK working tree changed")

    hashes = {}
    selections = (("backend", backend, ["src", "tests", "CMakeLists.txt", "cmake.toml", "MakeCommitHash.bat"]),
                  ("frontend", frontend, ["UEVR", "tests"]))
    for name, root, selected in selections:
        root = root.resolve()
        for relative in selected:
            start = root / relative
            if not start.exists():
                raise RuntimeError(f"Missing source input: {name}/{relative}")
            files = [start] if start.is_file() else []
            if start.is_dir():
                for parent, directories, names in os.walk(start):
                    directories[:] = sorted(d for d in directories if d not in {"bin", "obj", ".git", "__pycache__"})
                    files.extend(Path(parent) / filename for filename in sorted(names))
            for path in files:
                if not path.resolve().is_relative_to(root):
                    raise RuntimeError("Source input resolves outside its checkout")
                key = f"{name}/{path.relative_to(root).as_posix()}"
                if key in GENERATED_PATHS:
                    continue
                hashes[key] = hashlib.sha256(path.read_bytes()).hexdigest()
    return {"schema": 1, "pins": PINS, "sha256": hashes}


def verify_generated_outputs(backend: Path, frontend: Path, source_hashes: dict) -> dict:
    roots = {"backend": backend, "frontend": frontend}
    outputs = {}
    for key, metadata in GENERATED_OUTPUTS.items():
        name, relative = key.split("/", 1)
        path = roots[name] / relative
        if not path.is_file() or path.stat().st_size == 0:
            raise RuntimeError(f"Missing or empty generated build output: {key}")
        missing_inputs = [item for item in metadata["inputs"] if item not in source_hashes]
        if missing_inputs:
            raise RuntimeError(f"Generated output provenance input was not source-hashed: {key}: {missing_inputs}")
        outputs[key] = {
            **metadata,
            "size_bytes": path.stat().st_size,
            "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "input_sha256": {item: source_hashes[item] for item in metadata["inputs"]},
        }

    # CommitHash.autogenerated varies by build date, branch and dirty state,
    # but it must still identify the pinned backend and clean pinned SDK.
    identity_key = "backend/src/CommitHash.autogenerated"
    identity = (backend / "src/CommitHash.autogenerated").read_text(encoding="utf-8")
    macros = dict(re.findall(r'^[ \t]*#define[ \t]+(UEVR_[A-Z0-9_]+)[ \t]+"([^"]*)"[ \t]*$', identity, re.MULTILINE))
    expected_identity = {
        "UEVR_COMMIT_HASH": PINS["backend"],
        "UEVR_UESDK_COMMIT_HASH": PINS["sdk"],
        "UEVR_UESDK_TRACKED_DIRTY": "false",
    }
    for macro, expected in expected_identity.items():
        if macros.get(macro) != expected:
            raise RuntimeError(f"Generated build identity has unexpected {macro}: {macros.get(macro)!r}")
    outputs[identity_key]["identity_checks"] = expected_identity

    # Match the pinned frontend build's generator exactly, rather than merely
    # accepting any changed output at this path.
    plain = frontend / "UEVR/PlainTextFilteredExecutables.json"
    inputs = json.loads(plain.read_text(encoding="utf-8"))
    expected_filtered = json.dumps(
        [hashlib.sha256(item.encode()).hexdigest().upper() for item in inputs], indent=4)
    filtered_key = "frontend/UEVR/FilteredExecutables.json"
    filtered = (frontend / "UEVR/FilteredExecutables.json").read_text(encoding="utf-8")
    if filtered != expected_filtered:
        raise RuntimeError("Generated frontend executable hashes differ from the pinned generator output")
    outputs[filtered_key]["content_validation"] = "matches hash_executables.py output from unchanged PlainTextFilteredExecutables.json"

    return {
        "schema": 1,
        "pins": PINS,
        "outputs": outputs,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("mode", choices=["capture", "verify"])
    parser.add_argument("backend", type=Path)
    parser.add_argument("frontend", type=Path)
    parser.add_argument("checkpoint", type=Path)
    args = parser.parse_args()
    actual = inspect(args.backend, args.frontend)
    if args.mode == "capture":
        args.checkpoint.parent.mkdir(parents=True, exist_ok=True)
        args.checkpoint.write_text(json.dumps(actual, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(f"Captured {len(actual['sha256'])} patched source inputs; exact SDK unchanged.")
        return
    expected = json.loads(args.checkpoint.read_text(encoding="utf-8"))
    if expected.get("pins") != actual["pins"] or expected.get("schema") != actual["schema"]:
        raise RuntimeError("Source checkpoint provenance does not match")
    before, after = expected["sha256"], actual["sha256"]
    changed = [name for name in sorted(before.keys() | after.keys()) if before.get(name) != after.get(name)]
    if changed:
        raise RuntimeError("Build changed its source inputs: " + ", ".join(changed[:30]))
    generated = verify_generated_outputs(args.backend, args.frontend, after)
    generated_path = args.checkpoint.with_name(args.checkpoint.stem + "-generated.json")
    generated_path.write_text(json.dumps(generated, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"Verified {len(after)} patched source inputs; exact SDK unchanged.")
    print(f"Recorded {len(generated['outputs'])} generated build outputs and their source provenance in {generated_path}.")


if __name__ == "__main__":
    main()
